 * - `ERROR`: Trace encountered an error.
 * - `IN_PROGRESS`: Trace is currently in progress.
 */
export enum TraceState {
  /** Unspecified trace state */
  STATE_UNSPECIFIED = 'STATE_UNSPECIFIED',
  /** Trace successfully completed */
  OK = 'OK',
  /** Trace encountered an error */
  ERROR = 'ERROR',
  /** Trace is currently in progress */
  IN_PROGRESS = 'IN_PROGRESS'
}

/**
 * Convert an OpenTelemetry status code to the corresponding MLflow TraceState.
 * @param statusCode The OpenTelemetry span status code
