 * MLflow Trace Location module
 *
 * This module defines the types describing where a trace is stored.
 * MLflow currently supports two types of trace locations:
 *
 *   - MLflow experiment: The trace is stored in an MLflow experiment.
 *   - Inference table: The trace is stored in a Databricks inference table.
 */

/**
 * Enum representing the type of a trace location.
 */
export enum TraceLocationType {
  /** Unspecified trace location type */
  TRACE_LOCATION_TYPE_UNSPECIFIED = 'TRACE_LOCATION_TYPE_UNSPECIFIED',
  /** The trace is stored in an MLflow experiment */
  MLFLOW_EXPERIMENT = 'MLFLOW_EXPERIMENT',
  /** The trace is stored in a Databricks inference table */
  INFERENCE_TABLE = 'INFERENCE_TABLE'
}

/**
 * Represents the location of an MLflow experiment.
 */
export interface MlflowExperimentLocation {
  /** The ID of the MLflow experiment where the trace is stored */
  experimentId: string;
}

/**
 * Represents the location of a Databricks inference table.
 */
export interface InferenceTableLocation {
  /**
   * The fully qualified name of the inference table where the trace is stored,
   * in the format of `<catalog>.<schema>.<table>`.
   */
  fullTableName: string;
}

/**
 * Represents the location where the trace is stored.
 */
export interface TraceLocation {
  /** The type of the trace location */
  type: TraceLocationType;
  /** The MLflow experiment location. Set when the location type is MLflow experiment. */
  mlflowExperiment?: MlflowExperimentLocation;
  /** The inference table location. Set when the location type is Databricks inference table. */
  inferenceTable?: InferenceTableLocation;
}

/**
 * Create a TraceLocation for an MLflow experiment from the given experiment ID.
 * @param experimentId The ID of the MLflow experiment where the trace is stored
 * @returns A TraceLocation pointing at the given MLflow experiment
 */
export function createTraceLocationFromExperimentId(experimentId: string): TraceLocation {
  return {
    type: TraceLocationType.MLFLOW_EXPERIMENT,
    mlflowExperiment: { experimentId },
    inferenceTable: undefined
  };
}
